/                                    ← root
├── users/
│   ├── u_abc/  { name, status, ... }
│   └── u_def/  { ... }
├── rooms/
│   └── r_xyz/
│       ├── name: 'General'
│       ├── participants/
│       │   ├── u_abc: true
│       │   └── u_def: true
│       └── messages/
│           ├── -Mabc123/  { text, from, ts }
│           └── -Mdef456/  { text, from, ts }
└── presence/
    ├── u_abc: 'online'
    └── u_def: 'offline'

// KEY RULES OF THE MODEL:
// - Reading a node reads EVERYTHING below it. Depth is dangerous.
// - No JOINs, no cross-node queries.
// - Path segments are keys; values are JSON primitives or maps.
// - .push() generates monotonically-increasing IDs (like '-MabcXYZ').
// - Denormalize aggressively — flat data > nested data.

import 'package:firebase_database/firebase_database.dart';

final db = FirebaseDatabase.instance;

// Enable offline persistence — game-changer for mobile.
db.setPersistenceEnabled(true);

// ────── WRITE ──────
await db.ref('users/$uid').set({
  'name': 'Ada',
  'joinedAt': ServerValue.timestamp,
});

// Partial update:
await db.ref('users/$uid').update({'status': 'active'});

// Push (auto-generated key):
final ref = db.ref('rooms/$roomId/messages').push();
await ref.set({'text': 'Hello!', 'from': uid, 'ts': ServerValue.timestamp});
print('Message key: ${ref.key}');  // '-MabcXYZ'

// ────── DELETE ──────
await db.ref('users/$uid/tempField').remove();

// ────── READ (one-shot) ──────
final snap = await db.ref('users/$uid').get();
if (snap.exists) print(snap.value);

// ────── LISTEN (real-time) ──────
final sub = db.ref('rooms/$roomId/messages')
    .orderByChild('ts')
    .limitToLast(50)
    .onValue
    .listen((event) {
      final data = event.snapshot.value as Map<dynamic, dynamic>?;
      if (data == null) return;
      final messages = data.entries.map((e) => Message.fromMap(e.value)).toList();
      messages.sort((a, b) => a.ts.compareTo(b.ts));
      // Render messages
    });

// Also: onChildAdded, onChildChanged, onChildRemoved for granular events.

// Dispose:
await sub.cancel();

// ────── PAGINATION ──────
// RTDB pagination is fiddly. Common pattern:
final first = await db.ref('rooms/$roomId/messages')
    .orderByChild('ts').limitToLast(50).get();
// Get the earliest timestamp:
final firstMap = first.value as Map;
final earliestTs = firstMap.values
    .map((v) => v['ts'] as int)
    .reduce((a, b) => a < b ? a : b);
// Next page — messages OLDER than earliestTs:
final older = await db.ref('rooms/$roomId/messages')
    .orderByChild('ts')
    .endBefore(earliestTs)
    .limitToLast(50)
    .get();

// ────── TRANSACTION (optimistic) ──────
await db.ref('counters/likes').runTransaction((current) {
  final n = (current as int?) ?? 0;
  return Transaction.success(n + 1);
});
// If concurrent writers changed the value, tx retries automatically.

// ────── PRESENCE via onDisconnect ──────
final myPresence = db.ref('presence/$uid');
await myPresence.onDisconnect().set('offline');  // scheduled server-side
await myPresence.set('online');
// When the WebSocket drops (network dies, phone locks), the server runs the
// scheduled set('offline'). No client action needed. This is RTDB's superpower.

// realtime.rules.json — deployed via firebase deploy --only database
{
  "rules": {
    "users": {
      "$uid": {
        ".read": "auth.uid == $uid",
        ".write": "auth.uid == $uid",
        ".validate": "newData.hasChildren(['name', 'joinedAt']) && newData.child('name').isString()"
      }
    },
    "rooms": {
      "$roomId": {
        ".read": "data.child('participants').child(auth.uid).val() == true",
        "messages": {
          "$msgId": {
            ".write": "root.child('rooms').child($roomId).child('participants').child(auth.uid).val() == true"
          }
        }
      }
    },
    "presence": {
      "$uid": {
        ".read": "auth != null",
        ".write": "auth.uid == $uid"
      }
    }
  }
}

// KEY DIFFERENCES from Firestore rules:
// - JSON-based (not JS-based syntax).
// - CASCADING: if a parent grants read, ALL children are readable (no way to un-grant).
// - .read, .write, .validate at each node.
// - $var wildcards for path segments.
// - root, data, newData, auth as built-ins.
// - Default is deny.
